def find_enclosed_regions(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Start from border and flood fill 0s - these are not enclosed
    on_border_0 = set()
    queue = []
    for r in range(rows):
        for c in [0, cols-1]:
            if grid[r][c] == 0:
                queue.append((r, c))
                on_border_0.add((r, c))
    for c in range(cols):
