            if grid[r][c] == 0:
                if (r, c) not in queue:
                    queue.append((r, c))
                    on_border_0.add((r, c))

    visited_on_border = set()
    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        key = (r, c)
        if key in on_border_0 or grid[r][c] != 0:
            return False
        on_border_0.add(key)
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)
        return True

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                if (r,c) not in on_border_0:
                    print(f"Potential enclosed region at ({r},{c})")
                    # Do a simple BFS to count connected zeros
