def find_components(grid, target=0):
    visited = set()
    comps = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == target and (r,c) not in visited:
                comp = []
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp.append((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<len(grid) and 0<=nc<len(grid[0]) and grid[nr][nc]==target:
                            stack.append((nr,nc))
                comps.append(comp)
    return comps

def get_edges_touched(comp, rows, cols):
    """Get set of edges touched by component"""
    r_set = {r for r,_ in comp}
    c_set = {c for _,c in comp}

    edges = set()
    if 0 in r_set:
        edges.add('TOP')
    if (rows-1) in r_set:
        edges.add('BOTTOM')
    if 0 in c_set:
        edges.add('LEFT')
    if (cols-1) in c_set:
        edges.add('RIGHT')
    return edges

